package kr.memorynotes;
import android.content.Context;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;import java.time.LocalDate;
public class BackupManager {
 final Context context;final NoteDb db;
 public BackupManager(Context c,NoteDb db){this.context=c;this.db=db;}
 public static final long MAX_TOTAL=512L*1024*1024,MAX_META=32L*1024*1024,MAX_IMAGE=25L*1024*1024;
 public static void checkExportLimits(long metadata,long imageBytes,int images)throws IOException{if(metadata>MAX_META||metadata+imageBytes>MAX_TOTAL||images>10000)throw new IOException("백업 용량 제한을 초과했습니다. 사진 수 또는 용량을 줄여주세요");}
 public void exportTo(OutputStream output)throws Exception{
  JSONObject snapshot=db.snapshot();Set<String> files=new HashSet<>();JSONArray notes=snapshot.getJSONArray("notes");for(int i=0;i<notes.length();i++){Note n=Note.from(new JSONObject(notes.getJSONObject(i).getString("data")));for(int j=0;j<n.images.length();j++)files.add(n.images.getJSONObject(j).getString("file"));}
  byte[] metadata=snapshot.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);long total=0;for(String name:files){ZipGuard.checkName("images/"+name);File file=new File(new File(context.getFilesDir(),"images"),name);if(!file.isFile()||file.length()>MAX_IMAGE)throw new IOException("사진이 없거나 크기 제한을 초과했습니다");total+=file.length();}checkExportLimits(metadata.length,total,files.size());
  try(ZipOutputStream zip=new ZipOutputStream(new BufferedOutputStream(output))){zip.putNextEntry(new ZipEntry("notes.json"));zip.write(metadata);zip.closeEntry();for(String name:files){ZipGuard.checkName("images/"+name);File f=new File(new File(context.getFilesDir(),"images"),name);if(!f.isFile())throw new IOException("첨부 사진이 없어 백업을 완료하지 못했습니다");zip.putNextEntry(new ZipEntry("images/"+name));try(InputStream in=new FileInputStream(f)){copy(in,zip,25L*1024*1024);}zip.closeEntry();}}
 }
 public void validateAndRestore(InputStream input)throws Exception{
  File stage=new File(context.getCacheDir(),"restore-"+UUID.randomUUID());if(!stage.mkdirs())throw new IOException("복원 임시 공간을 만들 수 없습니다");ArrayList<File> installed=new ArrayList<>();boolean committed=false;
  try{
   Set<String> entries=new HashSet<>();long total=0;try(ZipInputStream zip=new ZipInputStream(new BufferedInputStream(input))){ZipEntry e;while((e=zip.getNextEntry())!=null){String name=e.getName();ZipGuard.checkName(name);if(e.isDirectory()||!entries.add(name))throw new IOException("중복 또는 잘못된 백업 항목입니다");if(entries.size()>10001)throw new IOException("백업 파일 수가 너무 많습니다");File f=new File(stage,name);File parent=f.getParentFile();if(!parent.exists()&&!parent.mkdirs())throw new IOException("임시 폴더를 만들 수 없습니다");try(OutputStream out=new FileOutputStream(f)){total+=copy(zip,out,name.equals("notes.json")?32L*1024*1024:25L*1024*1024);}if(total>512L*1024*1024)throw new IOException("백업은 512MB까지 복원할 수 있습니다");zip.closeEntry();}}
   if(!entries.contains("notes.json"))throw new IOException("노트 정보가 없는 백업입니다");String json;try(InputStream in=new FileInputStream(new File(stage,"notes.json"))){ByteArrayOutputStream bytes=new ByteArrayOutputStream();copy(in,bytes,32L*1024*1024);json=bytes.toString("UTF-8");}JSONObject snapshot=new JSONObject(json);validate(snapshot,entries);
   for(String entry:entries){if(entry.startsWith("images/")){android.graphics.BitmapFactory.Options bounds=new android.graphics.BitmapFactory.Options();bounds.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(new File(stage,entry).getPath(),bounds);if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException("손상되거나 지원하지 않는 사진이 있습니다");bounds.inJustDecodeBounds=false;int sample=1;while(bounds.outWidth/sample>2048||bounds.outHeight/sample>2048)sample*=2;bounds.inSampleSize=sample;android.graphics.Bitmap decoded=android.graphics.BitmapFactory.decodeFile(new File(stage,entry).getPath(),bounds);if(decoded==null)throw new IOException("손상된 사진이 있습니다");decoded.recycle();}}
   File dir=new File(context.getFilesDir(),"images");if(!dir.exists()&&!dir.mkdirs())throw new IOException("사진 저장 공간을 만들 수 없습니다");Map<String,String> mapping=new HashMap<>();for(String entry:entries){if(!entry.startsWith("images/"))continue;String old=entry.substring(7),next=UUID.randomUUID()+".img";File target=new File(dir,next);installed.add(target);try(InputStream in=new FileInputStream(new File(stage,entry));OutputStream out=new FileOutputStream(target)){copy(in,out,25L*1024*1024);}mapping.put(old,next);}
   JSONArray notes=snapshot.getJSONArray("notes");for(int i=0;i<notes.length();i++){JSONObject row=notes.getJSONObject(i);Note n=Note.from(new JSONObject(row.getString("data")));for(int j=0;j<n.images.length();j++){JSONObject im=n.images.getJSONObject(j);im.put("file",mapping.get(im.getString("file")));}row.put("data",n.json().toString());}db.restore(snapshot);committed=true;
  }finally{if(!committed)for(File f:installed)f.delete();removeTree(stage);}
 }
 static void validate(JSONObject o,Set<String> entries)throws Exception{
  if(o.getInt("version")!=1)throw new IOException("지원하지 않는 백업 버전입니다");
  Set<String> subjects=new HashSet<>(),chapters=new HashSet<>(),notes=new HashSet<>();Map<String,String> owners=new HashMap<>();
  JSONArray ss=o.getJSONArray("subjects");if(ss.length()==0)throw new IOException("과목이 없는 백업입니다");for(int i=0;i<ss.length();i++){JSONObject r=ss.getJSONObject(i);keys(r,"id","name");String id=r.getString("id");if(id.isEmpty()||r.getString("name").trim().isEmpty()||!subjects.add(id))throw new IOException("잘못된 과목 정보");}
  JSONArray cs=o.getJSONArray("chapters");for(int i=0;i<cs.length();i++){JSONObject r=cs.getJSONObject(i);keys(r,"id","subject","name");String id=r.getString("id"),s=r.getString("subject");if(id.isEmpty()||r.getString("name").trim().isEmpty()||!subjects.contains(s)||!chapters.add(id))throw new IOException("잘못된 단원 정보");owners.put(id,s);}
  JSONArray ns=o.getJSONArray("notes");for(int i=0;i<ns.length();i++){JSONObject r=ns.getJSONObject(i);keys(r,"id","data");JSONObject noteJson=new JSONObject(r.getString("data"));Note.requireComplete(noteJson);Note n=Note.from(noteJson);if(n.id.isEmpty()||!n.id.equals(r.getString("id"))||!notes.add(n.id)||!subjects.contains(n.subject)||(!n.chapter.isEmpty()&&!n.subject.equals(owners.get(n.chapter)))||n.title.trim().isEmpty()||n.rating< -1||n.rating>2||n.streak<0||!Arrays.asList("일반 노트","문답 카드","오답노트").contains(n.type))throw new IOException("잘못된 노트 정보");if(!n.due.isEmpty())LocalDate.parse(n.due);for(int j=0;j<n.images.length();j++){JSONObject im=n.images.getJSONObject(j);String f=im.getString("file");ZipGuard.checkName("images/"+f);if(!entries.contains("images/"+f))throw new IOException("사진이 누락된 백업입니다");JSONArray masks=im.getJSONArray("masks");for(int k=0;k<masks.length();k++){JSONArray rect=masks.getJSONArray(k);if(rect.length()!=4)throw new IOException("잘못된 사진 가림 정보");for(int q=0;q<4;q++){double v=rect.getDouble(q);if(Double.isNaN(v)||Double.isInfinite(v)||v<0||v>1)throw new IOException("잘못된 사진 좌표");}if(rect.getDouble(0)>=rect.getDouble(2)||rect.getDouble(1)>=rect.getDouble(3))throw new IOException("잘못된 사진 영역");}}}
  Set<Long> historyIds=new HashSet<>();JSONArray hs=o.getJSONArray("history");for(int i=0;i<hs.length();i++){JSONObject r=hs.getJSONObject(i);keys(r,"id","note","day","rating");if(!notes.contains(r.getString("note"))||!historyIds.add(r.getLong("id"))||r.getInt("rating")<0||r.getInt("rating")>2)throw new IOException("잘못된 복습 정보");LocalDate.parse(r.getString("day"));}
 }
 static void keys(JSONObject o,String...expected)throws IOException{Set<String> allowed=new HashSet<>(Arrays.asList(expected));Iterator<String> keys=o.keys();int count=0;while(keys.hasNext()){if(!allowed.contains(keys.next()))throw new IOException("알 수 없는 백업 필드입니다");count++;}if(count!=allowed.size())throw new IOException("필수 백업 필드가 없습니다");}
 static long copy(InputStream in,OutputStream out,long max)throws IOException{byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>max)throw new IOException("백업 항목 크기 제한을 초과했습니다");out.write(b,0,n);}return total;}
 static void removeTree(File f){File[] children=f.listFiles();if(children!=null)for(File c:children)removeTree(c);f.delete();}
}
